  "summary": "The code contains critical SSRF and performance vulnerabilities due to unvalidated proxying and memory-intensive buffering. The overall health is poor, requiring robust input validation, streaming, and production-grade configuration management.",
  "fixed_code": "const express = require('express');\nconst fetch = require('node-fetch');\nconst app = express();\n\n/**\n * Proxies a request to a target URL.\n * @param {string} url - The target URL to fetch.\n */\napp.get('/fetch-data', async (req, res) => {\n    const targetUrl = req.query.url;\n    if (!targetUrl) return res.status(400).send('URL is required');\n\n    try {\n        const url = new URL(targetUrl);\n        const allowedDomains = ['api.trusted.com'];\n        if (!allowedDomains.includes(url.hostname)) {\n            return res.status(400).send('Invalid URL');\n        }\n\n        const response = await fetch(targetUrl, { signal: AbortSignal.timeout(5000) });\n        if (!response.ok) throw new Error('Fetch failed');\n\n        res.setHeader('Content-Type', response.headers.get('content-type'));\n        response.body.pipe(res);\n    } catch (err) {\n        res.status(500).send('Error fetching data');\n    }\n});\n\napp.listen(process.env.PORT || 3000);"
}
